import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/services.dart';

import 'settings.dart';

/// The game's sounds (assets/sfx, generated by tool/sfx/make_sfx.py).
enum Snd { tap, select, correct, solvedOther, near, tick, timeup, turn, steal, hint, join, chat, win, end }

const _files = {
  Snd.tap: 'tap', Snd.select: 'select', Snd.correct: 'correct', Snd.solvedOther: 'solved_other',
  Snd.near: 'near', Snd.tick: 'tick', Snd.timeup: 'timeup', Snd.turn: 'turn', Snd.steal: 'steal',
  Snd.hint: 'hint', Snd.join: 'join', Snd.chat: 'chat', Snd.win: 'win', Snd.end: 'end',
};

/// Sound effects and haptics. Every call is fire-and-forget and never throws:
/// a missing audio device must not break a game.
class Sfx {
  static final _pools = <Snd, AudioPool>{};
  static final _last = <Snd, int>{};
  static bool enabled = true; // tests turn this off

  static Future<void> init() async {
    if (!enabled) return;
    for (final s in Snd.values) {
      try {
        _pools[s] = await AudioPool.create(
          source: AssetSource('sfx/${_files[s]}.wav'),
          maxPlayers: s == Snd.tick || s == Snd.chat || s == Snd.tap ? 3 : 2,
        );
      } catch (_) {/* no audio on this device: stay silent */}
    }
  }

  static void play(Snd s, {int minGapMs = 0}) {
    if (!enabled || !Settings.I.sound) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (minGapMs > 0 && now - (_last[s] ?? 0) < minGapMs) return;
    _last[s] = now;
    final pool = _pools[s];
    if (pool == null) return;
    unawaited(pool.start(volume: s == Snd.chat ? 0.5 : 1).then((_) {}, onError: (_) {}));
  }

  /* ---- haptics ---- */
  static void tick() => _h(HapticFeedback.selectionClick);
  static void light() => _h(HapticFeedback.lightImpact);
  static void medium() => _h(HapticFeedback.mediumImpact);
  static void heavy() => _h(HapticFeedback.heavyImpact);

  static void _h(Future<void> Function() f) {
    if (!enabled || !Settings.I.haptics) return;
    unawaited(f().then((_) {}, onError: (_) {}));
  }
}
